SELECT * from superex_trade.swap_margin
where symbol = #{symbol,jdbcType=VARCHAR}
and position>=#{position,jdbcType=BIGINT}
ORDER BY tier ASC
LIMIT 1

SELECT * from superex_trade.swap_margin
where symbol = #{symbol,jdbcType=VARCHAR}
and leverage>=#{leverage,jdbcType=BIGINT}
